export * as OTPField from './otp-field.tsx';
export type {
  RootOwnProps as OTPFieldRootOwnProps,
  RootProps as OTPFieldRootProps,
} from './otp-field.tsx';

@layer hj.components {
  /* Customise: --hj-otp-field-cell-width · --hj-otp-field-cell-height · --hj-otp-field-gap */
  .hj-otp-field {
    --_w: var(--hj-otp-field-cell-width, 48px);
    --_h: var(--hj-otp-field-cell-height, calc(56px * var(--hj-density-size)));
    display: inline-flex;
    align-items: center;
    gap: var(--hj-otp-field-gap, calc(8px * var(--hj-density)));
  }
  .hj-otp-field[data-size='sm'] {
    --_w: var(--hj-otp-field-cell-width, 40px);
    --_h: var(--hj-otp-field-cell-height, calc(48px * var(--hj-density-size)));
  }

  .hj-otp-field-input {
    --_ring: var(--hj-line);
    width: var(--_w);
    height: var(--_h);
    padding: 0;
    border: 0;
    border-radius: var(--hj-radius-sm);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--_ring);
    color: var(--hj-fg);
    font: 600 22px / 1 var(--hj-font-sans);
    font-variant-numeric: tabular-nums;
    text-align: center;
    caret-color: var(--hj-accent);
    outline: none;
    transition:
      box-shadow var(--hj-dur-fast) var(--hj-ease-out),
      background-color var(--hj-dur-base) var(--hj-ease-out),
      color var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-otp-field[data-size='sm'] .hj-otp-field-input {
    font-size: 19px;
  }
  .hj-otp-field-input:hover:not([data-disabled]):not(:focus) {
    --_ring: color-mix(in srgb, var(--hj-fg) 22%, transparent);
  }
  /* The active cell: accent ring. Its caret is the accent too. */
  .hj-otp-field-input:focus {
    --_ring: var(--hj-accent);
    box-shadow: inset 0 0 0 1.5px var(--_ring);
  }
  .hj-otp-field-input[data-filled] {
    background: var(--hj-surface-2);
    animation: hj-otp-field-fill var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle) both;
  }
  /* A paste fills left to right on the stagger clock (separators don't count: nth-of-type). */
  .hj-otp-field[data-pasting] .hj-otp-field-input[data-filled]:nth-of-type(2) {
    animation-delay: var(--hj-stagger);
  }
  .hj-otp-field[data-pasting] .hj-otp-field-input[data-filled]:nth-of-type(3) {
    animation-delay: calc(2 * var(--hj-stagger));
  }
  .hj-otp-field[data-pasting] .hj-otp-field-input[data-filled]:nth-of-type(4) {
    animation-delay: calc(3 * var(--hj-stagger));
  }
  .hj-otp-field[data-pasting] .hj-otp-field-input[data-filled]:nth-of-type(5) {
    animation-delay: calc(4 * var(--hj-stagger));
  }
  .hj-otp-field[data-pasting] .hj-otp-field-input[data-filled]:nth-of-type(6) {
    animation-delay: calc(5 * var(--hj-stagger));
  }
  .hj-otp-field[data-pasting] .hj-otp-field-input[data-filled]:nth-of-type(7) {
    animation-delay: calc(6 * var(--hj-stagger));
  }
  .hj-otp-field[data-pasting] .hj-otp-field-input[data-filled]:nth-of-type(8) {
    animation-delay: calc(7 * var(--hj-stagger));
  }
  @keyframes hj-otp-field-fill {
    from {
      color: transparent;
      transform: scale(calc(1 - 0.08 * var(--hj-travel)));
    }
  }
  .hj-otp-field-input[data-disabled] {
    background: transparent;
    color: var(--hj-fg-mute);
    cursor: not-allowed;
  }

  .hj-otp-field[data-status='error'] .hj-otp-field-input,
  .hj-otp-field-input[data-invalid] {
    --_ring: var(--hj-danger);
    box-shadow: inset 0 0 0 1.5px var(--_ring);
    caret-color: var(--hj-danger);
  }
  /* One nudge, never a shake: the only travel an error gets. */
  .hj-otp-field[data-status='error'] {
    animation: hj-otp-field-nudge 380ms var(--hj-ease-out);
  }
  @keyframes hj-otp-field-nudge {
    25% {
      transform: translateX(calc(-4px * var(--hj-travel)));
    }
    55% {
      transform: translateX(calc(4px * var(--hj-travel)));
    }
    80% {
      transform: translateX(calc(-2px * var(--hj-travel)));
    }
  }
  .hj-otp-field[data-status='success'] .hj-otp-field-input {
    --_ring: color-mix(in srgb, var(--hj-success) 55%, transparent);
    background: var(--hj-success-soft);
    color: var(--hj-success);
  }

  .hj-otp-field-separator {
    flex: none;
    width: 10px;
    height: 2px;
    border-radius: 2px;
    background: var(--hj-fg-mute);
    opacity: 0.6;
  }
}

'use client';
import { OTPField as Base } from '@base-ui/react/otp-field';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

/** A dash between groups of cells, e.g. 3 – 3. */
export const Separator: HanjiPart<typeof Base.Separator> = part(
  Base.Separator,
  'OTPField.Separator',
  'hj-otp-field-separator',
);

export interface RootOwnProps {
  /** error: wrong code (danger ring, one nudge) · success: accepted (success tint). */
  status?: 'idle' | 'error' | 'success';
  /** Cell size: md 48×56 (default), sm 40×48. */
  size?: 'sm' | 'md';
}
export interface RootProps extends RootOwnProps, Base.Root.Props {}

/**
 * A one-time code, one character per cell. With no children it renders `length` cells and
 * labels them; a paste fills the cells in a 24 ms cascade.
 *
 * @example <OTPField.Root length={6} onValueComplete={verify} />
 */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    status = 'idle',
    size = 'md',
    className,
    children,
    onValueChange,
    length,
    ...rest
  } = withDefaults(config, 'OTPField.Root', props);
  const [pasting, setPasting] = React.useState(false);
  React.useEffect(() => {
    if (!pasting) return undefined;
    const t = window.setTimeout(() => setPasting(false), 600);
    return () => window.clearTimeout(t);
  }, [pasting]);
  const handleChange: Base.Root.Props['onValueChange'] = (value, details) => {
    if (details.reason === 'input-paste') setPasting(true);
    onValueChange?.(value, details);
  };
  return (
    <Base.Root
      {...rest}
      length={length}
      onValueChange={handleChange}
      data-status={status === 'idle' ? undefined : status}
      data-size={size}
      data-pasting={pasting ? '' : undefined}
      className={cls(config, 'OTPField.Root', 'hj-otp-field', className)}
    >
      {children ??
        Array.from({ length }, (_, i) => (
          <Input
            // oxlint-disable-next-line react/no-array-index-key -- cells are positional
            key={i}
            aria-label={i === 0 ? undefined : config.strings.characterOf(i + 1, length)}
          />
        ))}
    </Base.Root>
  );
}

/** One cell. Its position in the paste cascade comes from its order among the cells. */
export const Input: HanjiPart<typeof Base.Input> = part(
  Base.Input,
  'OTPField.Input',
  'hj-otp-field-input',
);
